import { useMemo } from 'react';
import { getVoucherMerchantList } from '~/pages/voucher/model/get-voucher-merchant-list';
import { useGeolocationQuery } from '~/entities/shop/model/geolocation-model';
import type { Place } from '~/entities/shop/model/types';
import type { VoucherPlace } from '~/entities/voucher/api/dtos/voucher-item';

type VoucherMerchantListProps = {
  shopList: Place[];
  voucherPlaces: VoucherPlace[];
};

export const VoucherMerchantList = ({ shopList, voucherPlaces }: VoucherMerchantListProps) => {
  const { data: geolocation } = useGeolocationQuery();
  const placeList = useMemo(
    () => getVoucherMerchantList({ geolocation, shopList, voucherPlaces }),
    [geolocation, shopList, voucherPlaces],
  );

  return (
    <div
      className="bottom-sheet-content"
      data-testid="voucher-merchant-list"
      data-location-status={geolocation?.status}
    >
      <div className="merchant-sheet-container">
        <p className="total-count-text">
          총 <strong className="num common-font-roboto">{placeList.length}</strong>건
        </p>
        <ul className="merchant-card-list">
          {placeList.map((item) => (
            <li className="merchant-card-item" key={item.placeId}>
              <div className="card-top-info">
                <span className="category-name">{item.indutyInfo?.[0]?.indutyNm ?? ''}</span>
                <span className="distance-value common-font-roboto">{item.DISTANCE_NM}</span>
              </div>
              <strong className="merchant-store-name">{item.placeNm}</strong>
              <p className="merchant-address">{item.adres}</p>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};
